const allowedChannels = [];
const event = $input.first().json;
const data = event.data;
const limits = new Map([
  ["whatsapp", 4096],
  ["instagram", 1000],
  ["facebook", 2000],
]);
const limit = limits.get(event.channel_type);
if (
  event.event !== "message.received" ||
  !limit ||
  typeof event.channel_id !== "string" ||
  !allowedChannels.includes(event.channel_id) ||
  !data ||
  typeof data.message_id !== "string" ||
  !data.message_id.trim() ||
  data.message_id.length > 512 ||
  typeof data.from !== "string" ||
  !/^\+?[0-9]{3,30}$/.test(data.from) ||
  (event.channel_type !== "whatsapp" && data.from.startsWith("+"))
)
  return [];
let text;
if (data.type === "text" && typeof data.text === "string" && data.text.trim()) {
  let copy = data.text.slice(0, limit - 24);
  if (/[\uD800-\uDBFF]$/.test(copy)) copy = copy.slice(0, -1);
  if (copy !== data.text) copy += "…";
  text = 'You said: "' + copy + '" 👋';
} else if (
  ["image", "audio", "video", "document", "sticker", "file", "share"].includes(data.type)
) {
  const mime =
    typeof data.media?.mime_type === "string" &&
    /^[a-z0-9.+-]+\/[a-z0-9.+-]+$/i.test(data.media.mime_type) &&
    data.media.mime_type.length <= 100
      ? data.media.mime_type
      : "attachment";
  text = "Got your " + data.type + " 📎 — " + mime + ". Thanks!";
} else {
  return [];
}
return [
  {
    json: {
      key: JSON.stringify([event.channel_id, data.message_id]),
      channel: event.channel_id,
      recipient: data.from,
      text,
    },
  },
];

const value = $input.first().json;
if (
  !["sent", "queued"].includes(value.status) ||
  value.success !== true ||
  typeof value.message_id !== "string" ||
  !/^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i.test(value.message_id)
) {
  throw Error("Fiwano did not confirm or queue the reply. Check the dashboard before retrying.");
}
return [{ json: { receipt: value.message_id, status: value.status } }];
